package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.Aspect;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class InfernalFurnaceAudit {
 static final BlockPos BASE=FocalAudit.BASE.offset(80,0,80),CORE=BASE.offset(1,1,1);static int ticks;static volatile boolean ready,done;static InfernalFurnaceEntity furnace;
 static void check(boolean v,String s){if(!v)throw new IllegalStateException("TC4_INFERNAL FAIL "+s);System.out.println("TC4_INFERNAL PASS "+s);}
 static void prepare(ServerPlayer p){var l=p.serverLevel();p.getInventory().selected=0;RunicAudit.clear(p);p.getInventory().clearContent();p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();for(var cat:thaumcraft.api.research.ResearchCategories.researchCategories.values())for(var r:cat.research.values())DevCommands.grant(p.getPersistentData(),r.key,new HashSet<>());ThaumometerItem.sync(p,"");l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);
  for(int x=-5;x<=7;x++)for(int z=-5;z<=7;z++)for(int y=-1;y<=7;y++)l.setBlock(BASE.offset(x,y,z),y==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);
  for(int y=0;y<3;y++)for(int x=0;x<3;x++)for(int z=0;z<3;z++){Block block=x==1&&z==1?(y==2?Blocks.AIR:y==1?Blocks.LAVA:Blocks.OBSIDIAN):x%2==0&&z%2==0?Blocks.NETHER_BRICKS:y==1&&x==2&&z==1?Blocks.IRON_BARS:Blocks.OBSIDIAN;l.setBlock(BASE.offset(x,y,z),block.defaultBlockState(),2);}
  var empty=WandParts.make(WandParts.CAPS.get("gold"),WandParts.RODDEFS.get("greatwood"));check(!InfernalFurnaceCreation.create(l,BASE,p,empty),"insufficientvis rejectsformation");var wand=empty.copy();for(var a:Aspect.getPrimalAspects())WandData.add(wand,a,50,true);var expected=wand.copy();WandData.consumeCrafting(expected,new thaumcraft.api.aspects.AspectList().add(Aspect.FIRE,50).add(Aspect.EARTH,50),true,p);p.setItemInHand(InteractionHand.MAIN_HAND,wand);var click=BASE.above(2);var result=((BasicWandItem)wand.getItem()).onItemUseFirst(wand,new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(click.getCenter(),Direction.UP,click,false)));check(result.consumesAction()&&l.getBlockEntity(CORE) instanceof InfernalFurnaceEntity,"real wand interaction forms original3x3x3");for(var a:Aspect.getPrimalAspects())check(WandData.get(wand,a)==WandData.get(expected,a),"exact50Ignis50Terra capdiscount "+a.getTag());furnace=(InfernalFurnaceEntity)l.getBlockEntity(CORE);int converted=0;for(int y=0;y<3;y++)for(int x=0;x<3;x++)for(int z=0;z<3;z++)if(l.getBlockState(BASE.offset(x,y,z)).is(TC4Modern.INFERNAL_FURNACE.get()))converted++;check(converted==26&&l.isEmptyBlock(CORE.above()),"26convertedcells open top intact");check(l.getBlockState(CORE.east()).getValue(InfernalFurnaceBlock.PART)==10,"original east outlet");
  var fueless=new ItemStack(Items.IRON_ORE);check(furnace.accept(fueless),"accept smeltable withoutfuel");check(furnace.accept(new ItemStack(Items.STICK))&&furnace.contents.items.stream().noneMatch(s->s.is(Items.STICK)),"unsmeltableitem destroyedoriginal");
  p.connection.teleport(BASE.getX()+6,BASE.getY()+3,BASE.getZ()+6,135,20);p.getInventory().selected=8;ready=true;
 }
 static void finish(ServerPlayer p){var l=p.serverLevel();check(furnace.contents.items.stream().allMatch(ItemStack::isEmpty),"natural nofuel smelting consumesinput");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(CORE).inflate(5)).stream().anyMatch(e->e.getItem().is(Items.IRON_INGOT)),"natural outlet ejects iron ingot");var saved=furnace.saveWithFullMetadata(l.registryAccess());var copy=new InfernalFurnaceEntity(CORE,furnace.getBlockState());copy.loadWithComponents(saved,l.registryAccess());check(copy.contents.items.size()==32,"original32slot savedqueue");l.removeBlock(CORE,false);check(l.getEntitiesOfClass(net.minecraft.world.entity.monster.Blaze.class,new AABB(CORE).inflate(5)).stream().anyMatch(e->e.hasEffect(net.minecraft.world.effect.MobEffects.REGENERATION)&&e.hasEffect(net.minecraft.world.effect.MobEffects.FIRE_RESISTANCE)),"breakingcore releases enhancedblaze");check(l.getBlockState(BASE).is(Blocks.NETHER_BRICKS)&&l.getBlockState(BASE.offset(1,0,1)).is(Blocks.OBSIDIAN)&&l.getBlockState(CORE.east()).is(Blocks.IRON_BARS),"breakingcore restoresoriginalmaterials");l.getEntitiesOfClass(net.minecraft.world.entity.monster.Blaze.class,new AABB(CORE).inflate(10)).forEach(Entity::discard);done=true;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.furnaceAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==140){check(ready,"server formationpassed");LiquidDeathAudit.shot(mc,"infernal-furnace-formed.png");}if(ticks==250)LiquidDeathAudit.shot(mc,"infernal-furnace-smelted.png");if(ticks==280)server.execute(()->finish(server.getPlayerList().getPlayer(id)));if(ticks==300){check(done,"natural smelting/restoration passed");var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("INFERNALFURNACE"),0);mc.setScreen(book);}if(ticks==310)LiquidDeathAudit.shot(mc,"infernal-furnace-book-construct.png");if(ticks==320)((ThaumonomiconScreen)mc.screen).auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("INFERNALFURNACE"),2);if(ticks==330)LiquidDeathAudit.shot(mc,"infernal-furnace-book-2.png");if(ticks==340)mc.stop();}
}
